import { execFileSync } from 'node:child_process';
import { readFile, writeFile } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('../../', import.meta.url);
const schema = execFileSync(
  'cargo',
  ['run', '--locked', '--quiet', '-p', 'wuling-server', '--', '--export-openapi'],
  { cwd: root, encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 },
);
const types =
  '// Generated by pnpm api:generate. Do not edit.\n' +
  astToString(await openapiTS(JSON.parse(schema)));
for (const [name, content] of [
  ['openapi.json', schema],
  ['src/schema.d.ts', types],
]) {
  const file = new URL(`../packages/api-client/${name}`, import.meta.url);
  if (process.argv.includes('--check')) {
    if ((await readFile(file, 'utf8')) !== content) {
      throw new Error(`API contract drift: ${name}. Run pnpm api:generate and review the diff.`);
    }
  } else {
    await writeFile(file, content);
  }
}
